configs=[dict(kind='expense',slug='expense-report-template',name='Expense Report',title='Free Expense Report Template for Excel + Printable PDF',description='Prepare a business expense claim with receipt references, company-paid costs and advances. Free Excel, printable PDF and editable browser worksheet.',color='#245C52',headers=['Date','Merchant','Business purpose','Category','Paid by','Amount','Eligible','Receipt ref'],fields=common,extras=[['advance','Advance',60],['prior','Prior reimbursement',0]],sample={'reference':'EXP-2026-0042','person':'Example Employee','date':'2026-10-24','currency':'USD','party':'Example Workshop','due':'2026-10-24','notes':'Fictional service visit; policy reviewed manually','reviewer':'Example Reviewer','decision':'Draft','reviewDate':'','related':'VISIT-42','advance':'60','prior':'0','rows':[['2026-10-23','Example Rail','Service visit travel','Travel','Employee','120','120','R-101'],['2026-10-23','Example Supply','Job supplies','Supplies','Employee','40','40','R-102'],['2026-10-23','Example Parking','Service visit parking','Travel','Employee','18','18','R-103'],['2026-10-23','Example Hotel','Company-paid room','Travel','Company','50','0','R-104']]},summary=[['F23','Recorded costs'],['F24','Employee-paid eligible'],['F25','Advance'],['F26','Prior reimbursement'],['F27','Net reimbursement'],['F28','Review position']],example='Employee-paid eligible costs are $120 travel + $40 supplies + $18 parking = $178. A separate $50 company-paid room remains visible in recorded costs, but is excluded from the claim. Subtract the $60 advance and $0 prior reimbursement: $118 remains payable.',lead='Prepare one employee expense claim with an itemized record, receipt references and a reimbursement calculation. Keep company-paid costs visible while excluding them from the amount owed to the employee.',steps=[('Set the claim boundary','Use one claimant, report reference, reporting period and currency. Enter dates as fixed dates so the saved claim keeps the same period.'),('Record each cost','Enter the date, merchant, business purpose, category and receipt reference. Select Employee or Company for who paid. Keep the supporting documents with your own records.'),('Enter the eligible amount','For employee-paid rows, enter the amount your reviewer considers eligible. It cannot exceed the recorded cost. Company-paid rows must have eligible amount 0. Eligibility is a manual policy decision.'),('Reconcile money already provided','Enter advances and prior reimbursement once. If they exceed eligible costs, the negative net amount stays visible for a return or reconciliation review.'),('Review and retain','Check evidence and your policy, record the reviewer and status, then save a dated copy. A status entered in this worksheet is a record, not an approval signature or payment.')],unique=[('When the claim differs from the receipt','A $40 receipt with $35 eligible records both amounts; only $35 enters reimbursement. A company-paid item remains in recorded costs with eligible 0. This avoids paying the same cost twice.'),('Advances and corrections','If the advance changes to $200, the example net becomes -$22. Review the remaining advance with the employee; do not turn that result into zero. Correct an amount by revising the row and keeping the prior version under your process. Negative expense rows are not supported.'),('Receipts and tax treatment','A receipt reference helps you find a document; this worksheet does not upload or verify it. The IRS recordkeeping guidance describes supporting documents such as receipts and invoices. This form does not decide deductibility, mileage rates or tax treatment.')],faq=[('Does the template reimburse the employee?','No. It calculates from entered costs, eligibility, advances and prior payments. Your reviewer authorizes any reimbursement outside the worksheet.'),('Can I combine currencies?','Use one currency per report. Currency selection changes the label only. Convert amounts using your own documented process before entering them, or keep separate reports.'),('What if the eligible amount is unknown?','Leave it incomplete until the reviewer has checked it. Do not enter zero as a placeholder for an amount still being reviewed.')],links=[('/journal/small-business-budget-template-monthly-variance/','business budget variance guide'),('/journal/cash-flow-forecast-template-example/','cash-flow forecast example')],product='/planners/small-business-planner-2026-2028/',productName='Small Business Planner',source='https://www.irs.gov/businesses/small-businesses-self-employed/what-kind-of-records-should-i-keep',sourceName='IRS supporting business records'),
dict(kind='requisition',slug='purchase-requisition-template',name='Purchase Requisition',title='Free Purchase Requisition Template: Excel + PDF',description='Request an internal purchase with quantities, estimated costs, budget and a manual approval record. Download free Excel and PDF forms or use the worksheet.',color='#344F80',headers=['Item / SKU','Description','Unit','Quantity','Est. unit cost','Line estimate','Suggested supplier','Quote ref'],fields=common,extras=[['shipping','Estimated shipping',10],['tax','Estimated tax',0],['budget','Available budget',160]],sample={'reference':'REQ-2026-0042','person':'Example Requester','date':'2026-10-24','currency':'USD','party':'Workshop maintenance','due':'2026-10-30','notes':'Replace service stock; fictional request, not approved','reviewer':'Example Manager','decision':'Draft','reviewDate':'','related':'','shipping':'10','tax':'0','budget':'160','rows':[['FIL-01','Replacement filters','each','20','6','','Example Supply','Q-42'],['GLV-02','Workshop gloves','pair','5','8','','Example Supply','Q-42']]},summary=[['F23','Estimated shipping'],['F24','Estimated tax'],['F25','Estimated request'],['F26','Available budget'],['F27','Budget headroom'],['F28','Cost review']],example='Request 20 filters at $6 each and 5 pairs of gloves at $8, plus $10 shipping and $0 entered tax. The estimate is $120 + $40 + $10 = $170. Against an entered $160 budget, headroom is -$10. Reducing filters to 18 changes the estimate to $158 and headroom to $2; neither result approves the purchase.',lead='Request an internal purchase before anyone places an order with a supplier. Record what is needed, estimated costs, budget context and a separate manual approval decision.',steps=[('Describe the need','Enter a unique request reference, requester, department, need-by date and business reason. A request should explain the work that will be delayed if the items are unavailable.'),('List items in buying units','Use quantity and estimated price for the same unit. Twenty each at $6 is different from twenty boxes at $6. Add a suggested supplier and quote reference when known.'),('Add estimated charges','Enter shipping and tax as amounts in the selected currency. These are estimates you supply; the form does not look up supplier prices or tax rates.'),('Compare with the available budget','Enter the budget available for this request. Negative headroom calls for a revised request or a budget decision. Positive headroom is only a cost comparison.'),('Record the separate approval','The reviewer enters a decision and fixed review date under your process. If the request proceeds, create the supplier PO separately and add its reference. Retain both versions.')],unique=[('Requisition, purchase order and invoice','The requisition records an internal need. A purchase order records the order issued to a supplier. An invoice is a request for payment. Keep separate references so an internal estimate does not become an unintended supplier order.'),('Keep budget fit separate from approval','The example is $10 over the entered budget. Changing the quantity to 18 leaves $2 headroom, while the manual status remains Draft. The worksheet does not check spending authority, existing commitments or departmental policy.'),('What to do when a quote changes','Update the estimated price and quote reference before review, then save a version. If a supplier order already exists, handle the change through that purchasing process rather than replacing the historical request.')],faq=[('Is this an employee hiring requisition?','No. This resource requests goods or services for an internal purchase. It does not manage recruitment or employee headcount.'),('Does an Approved status issue a purchase order?','No. Status is a manual record only. The worksheet neither verifies the approver nor sends an order. Prepare and review a separate PO.'),('Can I use it for services?','Yes, when quantity and unit describe the service clearly, such as 2 hours at a quoted hourly amount. Keep the agreed scope and quote reference with the request.')],links=[('/tools/purchase-order-template/','supplier purchase-order form'),('/journal/purchase-order-tracker/','purchase-order tracker'),('/tools/supplier-quote-comparison/','supplier quote comparison')],product='/planners/inventory-procurement-planner/',productName='Inventory & Procurement Planner',source='https://docs.oracle.com/en/cloud/saas/procurement/25d/oaprc/considerations-for-purchase-order-creation.html',sourceName='Oracle purchase-order creation documentation'),
dict(kind='order',slug='customer-order-form',name='Customer Order Form',title='Free Customer Order Form Template: Excel + Printable PDF',description='Capture a customer order with items, variants, delivery details and a paid-to-date balance. Free Excel, printable PDF and a local browser worksheet.',color='#8A493A',headers=['SKU','Item','Size / color / unit','Quantity','Unit price','Line amount','Delivery note','Item note'],fields=common,extras=[['shipping','Shipping',8],['tax','Entered tax',0],['discount','Discount',0],['paid','Paid to date',30]],sample={'reference':'ORD-2026-0042','person':'Example Seller','date':'2026-10-24','currency':'USD','party':'Example Customer','due':'2026-10-30','notes':'Collect at workshop; confirm availability separately','reviewer':'Example Seller','decision':'Draft','reviewDate':'','related':'PAY-42','shipping':'8','tax':'0','discount':'0','paid':'30','rows':[['TS-M','Workshop T-shirt','Medium / blue / each','2','25','','Collect',''],['CAP-1','Workshop cap','One size / each','1','20','','Collect','']]},summary=[['F23','Shipping'],['F24','Entered tax'],['F25','Discount'],['F26','Order total'],['F27','Paid to date'],['F28','Balance remaining'],['F29','Payment position']],example='Two T-shirts at $25 each plus one $20 cap produce $70 in items. Add $8 shipping, $0 entered tax and $0 discount: the order total is $78. Record $30 paid to date with its payment reference: $48 remains. All names and amounts are fictional.',lead='Capture one customer order before packing or invoicing. Record item variants, quantities, delivery arrangements and an amount paid to date, then keep a reviewed copy of the request.',steps=[('Identify the request','Enter a unique order reference, fixed date, seller and customer label. Use the notes for contact or delivery details only when needed, and store the saved copy appropriately.'),('Specify the exact item','Use SKU, item and size/color or unit to avoid variant confusion. Check availability separately before promising a delivery date.'),('Review the price','Enter positive quantities and nonnegative unit prices. Enter shipping, tax and discount as amounts. The worksheet does not calculate jurisdiction-specific tax or convert currencies.'),('Record payments separately','Enter only the cumulative amount actually paid and keep a payment reference. A requested deposit is not a received payment. For two payments, add them once to the cumulative paid amount.'),('Confirm and preserve changes','Record the manual status and review date, agree any changes with the customer, then save a version. Use a packing slip for what is shipped and an invoice for an amount requested.')],unique=[('Keep the original order intact during partial fulfilment','If one T-shirt ships first, the original request still shows two T-shirts and one cap. Record the parcel on a packing slip and keep the remaining quantities in an order tracker. Do not reduce the original quantity merely to match one shipment.'),('An overpayment stays visible','If the fictional customer pays $80 against a $78 order, the balance is -$2 and the worksheet calls for an overpayment review. It does not silently cap the payment or issue a refund.'),('What the form sends to the customer','The browser form is a local worksheet. Saving or printing does not submit it to your customer or your shop. Review the details, then share the reviewed file through your own process. It has no checkout, inventory reservation or order inbox.')],faq=[('Can customers submit this form online?','No. It is an editable local worksheet and downloadable form. It does not collect submissions or send entered details to NexalyPlanner.'),('Is this also an invoice or receipt?','No. It records a customer request. Use a separate invoice to request payment and a receipt to acknowledge money received, with matching references.'),('Can I track several orders in this workbook?','This file is for one order. Save a separate copy per order and use the order-tracking guide for a multi-order record.')],links=[('/tools/packing-slip-template/','packing-slip template'),('/journal/track-small-business-orders/','small-business order tracker'),('/tools/invoice-collection-schedule/','invoice collection schedule')],product='/planners/sales-management-system/',productName='Sales Management System & Inventory Tracker',source=None,sourceName=None)]
